<body>
<div class="left">
  <h1>CHIP-8 Emulator</h1>
  <div class="panel">
    <canvas id="screen" width="640" height="320"></canvas>
  </div>
  <div class="panel row">
    <button id="btnRun">Run</button>
    <button id="btnPause">Pause</button>
    <button id="btnStep">Single Step</button>
